import type {
  ColumnFiltersState,
  PaginationState,
  SortingState,
} from "@tanstack/react-table";
import type { TableAPI } from "@/components/config-table/lib";

/* eslint-disable @typescript-eslint/no-explicit-any */
export interface SelectOption {
  label: string;
  value: string;
}

export interface ColumnConfig<TData, TKey extends keyof TData = keyof TData> {
  id: string;
  header: string;
  accessorKey: TKey;
  type: "text" | "select" | "multiselect" | "number" | "boolean" | "date";
  width?: number;
  sortable?: boolean;
  filtering?: {
    enabled: boolean;
    filterType?: "text" | "number" | "select" | "date";
    filterOptions?: {
      value: string;
      label: string;
    }[];
  };
  editable?: boolean;
  options?: SelectOption[];
  placeholder?: string;
  validation?: {
    required?: boolean;
    min?: number;
    max?: number;
    pattern?: string;
  };
}

export interface TableConfig<TData> {
  tableKey: string;
  columns: ColumnConfig<TData>[];
  data: TData[];

  pagination?: {
    enabled: boolean;
    pageSize: number;
    pageSizeOptions: number[];
    onPaginationChange?: (pagination: PaginationState) => void;
  };

  sorting?: {
    enabled: boolean;
    onColumnSortingChange?: (value: SortingState) => void;
  };

  filtering?: {
    enabled: boolean;
    globalSearch?: boolean;
    onGlobalFilterChange?: (value: string) => void;
    onColumnFilterChange?: (value: ColumnFiltersState) => void;
  };

  editing?: {
    enabled: boolean;
    apiBaseUrl?: string;
    idField: keyof TData;

    rowCreating?: {
      enabled: boolean;
      requiredFields?: (keyof TData)[];
      defaultValues?: Partial<TData>;
      autoSave?: boolean;
      autoSaveDelay?: number;
      customCreateHandler?: (
        newRowData: TData,
        tableAPI: TableAPI<TData>
      ) => Promise<boolean>;
      onRowCreated?: (newRow: TData, response: any) => void;
      onCreateError?: (error: any, rowData: TData) => void;
    };

    columnUpdating?: {
      customUpdateHandler?: (
        rowData: TData,
        columnId: keyof TData,
        newValue: any,
        oldValue: any,
        tableAPI: TableAPI<TData>
      ) => Promise<boolean>;

      relatedUpdates?: Array<{
        condition: (
          columnId: keyof TData,
          newValue: any,
          rowData: TData
        ) => boolean;
        endpoint: string;
        method: "POST" | "PATCH" | "PUT" | "DELETE";
        body: (rowData: TData, columnId: keyof TData, newValue: any) => any;
        headers?: Record<string, string>;
      }>;

      columnEndpoints?: Partial<
        Record<
          keyof TData,
          {
            endpoint: string;
            method: "POST" | "PATCH" | "PUT" | "DELETE";
            body: (rowData: TData, newValue: any, oldValue: any) => any;
            headers?: Record<string, string>;
          }
        >
      >;

      beforeUpdate?: (
        rowData: TData,
        columnId: keyof TData,
        newValue: any
      ) => Promise<boolean> | boolean;

      afterUpdate?: (
        rowData: TData,
        columnId: keyof TData,
        newValue: any,
        response: any
      ) => Promise<void> | void;
    };

    onCellEdit?: (
      rowIndex: number,
      columnId: keyof TData,
      newValue: any,
      oldValue: any,
      rowData: TData
    ) => Promise<boolean> | boolean;

    onRowEdit?: (
      rowIndex: number,
      newData: TData,
      oldData: TData
    ) => Promise<boolean> | boolean;

    onApiError?: (
      error: any,
      context: { operation: string; rowIndex: number; columnId?: keyof TData }
    ) => void;
  };
}

/* eslint-disable @typescript-eslint/no-explicit-any */
export // Enhanced API utility class for complex scenarios
class TableAPI<TData> {
  private baseUrl: string;
  private tableKey: string;
  private idField: keyof TData;

  constructor(
    tableKey: string,
    baseUrl: string = "/api",
    idField: keyof TData = "id" as keyof TData
  ) {
    this.baseUrl = baseUrl.replace(/\/$/, ""); // Remove trailing slash
    this.tableKey = tableKey;
    this.idField = idField;
  }

  // Build API endpoint for table operations
  private getEndpoint(id?: TData[keyof TData]): string {
    const endpoint = `${this.baseUrl}/${this.tableKey}`;
    return id ? `${endpoint}?id=eq.${id as string}` : endpoint;
  }

  // Generic API call method
  async makeRequest(endpoint: string, options: RequestInit): Promise<any> {
    try {
      const response = await fetch(endpoint, {
        headers: {
          "Content-Type": "application/json",
          ...options.headers,
        },
        ...options,
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          errorData.message || `HTTP ${response.status}: ${response.statusText}`
        );
      }

      // Handle different response types
      const contentType = response.headers.get("content-type");
      if (contentType && contentType.includes("application/json")) {
        return await response.json();
      }
      return await response.text();
    } catch (error) {
      console.error("API request failed:", error);
      throw error;
    }
  }

  // Update a single cell/field
  async updateCell(
    rowData: TData,
    columnId: keyof TData,
    newValue: any
  ): Promise<boolean> {
    const id = rowData[this.idField];
    if (!id) {
      throw new Error(
        `Row missing ${this.idField as string} field for API update`
      );
    }

    await this.makeRequest(this.getEndpoint(id), {
      method: "PATCH",
      body: JSON.stringify({ [columnId]: newValue }),
    });

    return true;
  }

  // Custom endpoint update
  async updateWithCustomEndpoint(
    endpoint: string,
    method: "POST" | "PATCH" | "PUT" | "DELETE",
    body: any,
    headers?: Record<string, string>
  ): Promise<any> {
    return await this.makeRequest(endpoint, {
      method,
      body: JSON.stringify(body),
      headers,
    });
  }

  // Batch update multiple rows/cells
  async batchUpdate(
    updates: Array<{
      id: string | number;
      data: Record<string, any>;
    }>,
    customEndpoint?: string
  ): Promise<any> {
    const endpoint = customEndpoint || `${this.getEndpoint()}/batch`;

    return await this.makeRequest(endpoint, {
      method: "PATCH",
      body: JSON.stringify({ updates }),
    });
  }

  // Transaction-based updates
  async executeTransaction(
    operations: Array<{
      endpoint: string;
      method: string;
      body: any;
    }>,
    transactionEndpoint?: string
  ): Promise<any> {
    const endpoint = transactionEndpoint || `${this.baseUrl}/transaction`;

    return await this.makeRequest(endpoint, {
      method: "POST",
      body: JSON.stringify({ operations }),
    });
  }

  // Update entire row
  async updateRow(rowData: TData, updates: Partial<TData>): Promise<boolean> {
    const id = rowData[this.idField];
    if (!id) {
      throw new Error(
        `Row missing ${this.idField as string} field for API update`
      );
    }

    await this.makeRequest(this.getEndpoint(id), {
      method: "PATCH",
      body: JSON.stringify(updates),
    });

    return true;
  }

  // Create new row
  async createRow(data: Record<string, any>): Promise<any> {
    return await this.makeRequest(this.getEndpoint(), {
      method: "POST",
      headers: {
        Prefer: "return=representation",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(data),
    });
  }

  // Delete row
  async deleteRow(rowData: TData): Promise<boolean> {
    const id = rowData[this.idField];
    if (!id) {
      throw new Error(
        `Row missing ${this.idField as string} field for API delete`
      );
    }

    await this.makeRequest(this.getEndpoint(id), {
      method: "DELETE",
    });

    return true;
  }

  // Fetch table data
  async fetchData(params?: Record<string, any>): Promise<any> {
    const url = new URL(this.getEndpoint(), window.location.origin);
    if (params) {
      Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
          url.searchParams.append(key, String(value));
        }
      });
    }

    return await this.makeRequest(url.toString(), { method: "GET" });
  }
}

